// ---------------------------------------------------------------------------
// Persistent worker pool for the SDF field map.
//
// PERMITTED SHAPE ONLY: a parallel map with a deterministic per-element write.
// The output buffer is sized before the region opens, each task owns a disjoint
// half-open range of grid PLANES, element p's value is a pure function of p and
// read-only snapshots, and no Maya API is touched inside a worker. There is no
// reduction and no shared accumulator, so the answer cannot depend on the
// thread count or on where the chunk boundaries land.
//
// The chunk cursor is a MEMBER of the pool, never file-scope: Maya's EM can
// have two instances of this node inside a region at the same time, and a
// shared cursor would let each rewind the other's range.
class NDFieldPool {
public:
    NDFieldPool() {}
    ~NDFieldPool() { shutdown(); }

    NDFieldPool(const NDFieldPool&) = delete;
    NDFieldPool& operator=(const NDFieldPool&) = delete;

    // Worker count: hardware_concurrency - 1 (the calling thread also drains),
    // capped at 8, overridable without a rebuild.
    static int desired_workers() {
        const char* env = std::getenv("MPYNODE_METABALLS_THREADS");
        if (env && *env) {
            long v = std::strtol(env, nullptr, 10);
            if (v < 1) v = 1;
            if (v > 64) v = 64;
            return (int)v - 1;
        }
        unsigned hc = std::thread::hardware_concurrency();
        if (hc < 2u) return 0;
        int w = (int)hc - 1;
        if (w > 7) w = 7;
        return w;
    }

    void shutdown() {
        {
            std::unique_lock<std::mutex> lk(_m);
            if (_workers.empty()) return;
            _stop = true;
        }
        _cv_go.notify_all();
        for (auto& t : _workers) { if (t.joinable()) t.join(); }
        _workers.clear();
        _stop = false;
    }

    // Run body over [0, total) in dynamic chunks. Blocks until every chunk has
    // been retired, so no worker outlives the compute() that opened the region.
    void run(int64_t total, int64_t chunk,
             const std::function<void(int64_t, int64_t)>& body) {
        if (total <= 0) return;
        if (chunk < 1) chunk = 1;
        int want = desired_workers();
        if (want < 0) want = 0;
        if ((int)_workers.size() != want) {
            shutdown();
            for (int i = 0; i < want; ++i) {
                _workers.emplace_back([this]() { this->_worker_loop(); });
            }
        }
        if (_workers.empty()) { body(0, total); return; }
        {
            std::unique_lock<std::mutex> lk(_m);
            _body = &body;
            _total = total;
            _chunk = chunk;
            _cursor.store(0, std::memory_order_relaxed);
            _pending = (int)_workers.size();
            ++_gen;
        }
        _cv_go.notify_all();
        _drain();                       // the calling thread pulls chunks too
        {
            std::unique_lock<std::mutex> lk(_m);
            _cv_done.wait(lk, [this]() { return _pending == 0; });
            _body = nullptr;
        }
    }

private:
    void _drain() {
        const std::function<void(int64_t, int64_t)>* fn = _body;
        const int64_t total = _total, chunk = _chunk;
        for (;;) {
            int64_t lo = _cursor.fetch_add(chunk, std::memory_order_relaxed);
            if (lo >= total) break;
            int64_t hi = lo + chunk;
            if (hi > total) hi = total;
            (*fn)(lo, hi);
        }
    }

    void _worker_loop() {
        uint64_t seen = 0;
        for (;;) {
            {
                std::unique_lock<std::mutex> lk(_m);
                _cv_go.wait(lk, [this, &seen]() { return _stop || _gen != seen; });
                if (_stop) return;
                seen = _gen;
            }
            _drain();
            bool last = false;
            {
                std::unique_lock<std::mutex> lk(_m);
                last = (--_pending == 0);
            }
            if (last) _cv_done.notify_all();
        }
    }

    std::vector<std::thread> _workers;
    std::mutex _m;
    std::condition_variable _cv_go;
    std::condition_variable _cv_done;
    bool _stop = false;
    uint64_t _gen = 0;
    int _pending = 0;
    std::atomic<int64_t> _cursor{0};
    int64_t _total = 0;
    int64_t _chunk = 1;
    const std::function<void(int64_t, int64_t)>* _body = nullptr;
};


class Metaballs : public MPxNode {
public:
    Metaballs() {}
    ~Metaballs() override { _fieldPool.shutdown(); }
    NDFieldPool _fieldPool;
    static void*   creator() { return new Metaballs(); }
    static MStatus initialize();
    MStatus        compute(const MPlug& plug, MDataBlock& data) override;
    static MTypeId id;
    static MObject aShapeMatrix;
    static MObject aShapeType;
    static MObject aAdditive;
    static MObject aSmoothing;
    static MObject aRadius;
    static MObject aHeight;
    static MObject aAxis;
    static MObject aHalfExtents;
    static MObject aResolution;
    static MObject aIsoValue;
    static MObject aOutMesh;
};

