MStatus Metaballs::initialize() {
    MFnNumericAttribute nAttr;
    MFnUnitAttribute    uAttr;
    MFnEnumAttribute    eAttr;
    MFnMatrixAttribute  mAttr;
    MFnTypedAttribute   tAttr;
    MFnCompoundAttribute cAttr;

    aShapeMatrix = mAttr.create("shapeMatrix", "shapeMatrix", MFnMatrixAttribute::kDouble);
    mAttr.setStorable(true);
    mAttr.setArray(true);
    mAttr.setKeyable(false);
    aShapeType = nAttr.create("shapeType", "shapeType", MFnNumericData::kInt, 0);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aAdditive = nAttr.create("additive", "additive", MFnNumericData::kBoolean, true);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aSmoothing = nAttr.create("smoothing", "smoothing", MFnNumericData::kDouble, 0.0);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aRadius = nAttr.create("radius", "radius", MFnNumericData::kDouble, 0.0);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aHeight = nAttr.create("height", "height", MFnNumericData::kDouble, 1.0);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aAxis = nAttr.create("axis", "axis", MFnNumericData::kInt, 1);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    MObject aHalfExtentsX = nAttr.create("halfExtentsX", "halfExtentsX", MFnNumericData::kDouble, 0.0);
    MObject aHalfExtentsY = nAttr.create("halfExtentsY", "halfExtentsY", MFnNumericData::kDouble, 0.0);
    MObject aHalfExtentsZ = nAttr.create("halfExtentsZ", "halfExtentsZ", MFnNumericData::kDouble, 0.0);
    aHalfExtents = nAttr.create("halfExtents", "halfExtents", aHalfExtentsX, aHalfExtentsY, aHalfExtentsZ);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    nAttr.setArray(true);
    nAttr.setKeyable(false);
    aResolution = nAttr.create("resolution", "resolution", MFnNumericData::kInt, 8);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    aIsoValue = nAttr.create("isoValue", "isoValue", MFnNumericData::kDouble, 0.0);
    nAttr.setStorable(true);
    nAttr.setKeyable(true);
    aOutMesh = tAttr.create("outMesh", "out", MFnData::kMesh);
    tAttr.setWritable(false);
    tAttr.setStorable(false);

    addAttribute(aShapeMatrix);
    addAttribute(aShapeType);
    addAttribute(aAdditive);
    addAttribute(aSmoothing);
    addAttribute(aRadius);
    addAttribute(aHeight);
    addAttribute(aAxis);
    addAttribute(aHalfExtents);
    addAttribute(aResolution);
    addAttribute(aIsoValue);
    addAttribute(aOutMesh);

    attributeAffects(aShapeMatrix, aOutMesh);
    attributeAffects(aShapeType, aOutMesh);
    attributeAffects(aAdditive, aOutMesh);
    attributeAffects(aSmoothing, aOutMesh);
    attributeAffects(aRadius, aOutMesh);
    attributeAffects(aHeight, aOutMesh);
    attributeAffects(aAxis, aOutMesh);
    attributeAffects(aHalfExtents, aOutMesh);
    attributeAffects(aResolution, aOutMesh);
    attributeAffects(aIsoValue, aOutMesh);
    return MS::kSuccess;
}

// ==== bundled commands (Methods @maya_command) ====

// Stringify a flag value for the argument blob; Python re-types it from the
// kind tag that travels with it.
static std::string _str(const MString& v) { return std::string(v.asChar()); }
static std::string _str(int v) { std::ostringstream o; o << v; return o.str(); }
static std::string _str(bool v) { return v ? "1" : "0"; }
static std::string _str(double v) {
    std::ostringstream o; o.precision(17); o << v; return o.str();
}


