MStatus initializePlugin(MObject obj) {
    MFnPlugin plugin(obj, "mpynode-native", "1.0+43cbe907441e", "Any");
    MStatus st = plugin.registerNode("metaballs", Metaballs::id, Metaballs::creator, Metaballs::initialize);
    if (!st) return st;
    MStatus _cs_AddSphereCmd = plugin.registerCommand("addSphere", AddSphereCmd::creator, AddSphereCmd::newSyntax); if (!_cs_AddSphereCmd) return _cs_AddSphereCmd;
    MStatus _cs_AddBoxCmd = plugin.registerCommand("addBox", AddBoxCmd::creator, AddBoxCmd::newSyntax); if (!_cs_AddBoxCmd) return _cs_AddBoxCmd;
    MStatus _cs_AddCylinderCmd = plugin.registerCommand("addCylinder", AddCylinderCmd::creator, AddCylinderCmd::newSyntax); if (!_cs_AddCylinderCmd) return _cs_AddCylinderCmd;
    MStatus _cs_MetaballsCmd = plugin.registerCommand("metaballs", MetaballsCmd::creator, MetaballsCmd::newSyntax); if (!_cs_MetaballsCmd) return _cs_MetaballsCmd;
    return st;
}
MStatus uninitializePlugin(MObject obj) {
    MFnPlugin plugin(obj);
    plugin.deregisterCommand("addSphere");
    plugin.deregisterCommand("addBox");
    plugin.deregisterCommand("addCylinder");
    plugin.deregisterCommand("metaballs");
    return plugin.deregisterNode(Metaballs::id);
}
